package ama.localdev;

import ama.worker.*;import ama.transcript.*;import ama.storage.*;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import java.lang.reflect.*;import java.sql.*;import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.AbstractDataSource;import org.springframework.core.env.*;import com.fasterxml.jackson.databind.ObjectMapper;

/** Genuine capacity-one minutes pool alongside actual TXT and marked-publication reconciliation. */
public final class LocalWorkerCoexistenceCheck {
 static final ObjectMapper JSON=new ObjectMapper();
 static void check(boolean b,String m){if(!b)throw new IllegalStateException(m);}
 static final class Source extends AbstractDataSource {
  final DataSource delegate;final CountDownLatch arrived=new CountDownLatch(1),resume=new CountDownLatch(1);final AtomicBoolean once=new AtomicBoolean();final List<Map<String,Object>> locks=Collections.synchronizedList(new ArrayList<>());final AtomicLong serial=new AtomicLong();volatile boolean armed;
  Source(DataSource s){delegate=s;}
  static Object invoke(Object o,Method m,Object[] a)throws Throwable{try{return m.invoke(o,a);}catch(InvocationTargetException e){throw e.getCause();}}
  Object proxy(Object o,Class<?> t,InvocationHandler h){return Proxy.newProxyInstance(t.getClassLoader(),new Class[]{t},h);}
  Connection wrap(Connection actual){long id=serial.incrementAndGet();var captured=new AtomicBoolean();return(Connection)proxy(actual,Connection.class,(p,m,a)->{
   if(m.getName().equals("equals"))return p==a[0];if(m.getName().equals("hashCode"))return System.identityHashCode(p);Object result=invoke(actual,m,a);boolean target=Thread.currentThread().getName().startsWith("ama-work-MINUTES_GENERATE-");
   if(armed&&target&&m.getName().equals("commit")&&captured.get()&&once.compareAndSet(false,true)){arrived.countDown();check(resume.await(23,TimeUnit.SECONDS),"Bounded actual S release required");}
   if(m.getName().equals("prepareStatement")&&a[0] instanceof String sql&&result instanceof PreparedStatement st){var params=new TreeMap<Integer,Object>();return proxy(st,PreparedStatement.class,(s,sm,sa)->{
    if(sm.getName().startsWith("set")&&sa!=null&&sa.length>=2&&sa[0] instanceof Integer n)params.put(n,sa[1]);
    if(sm.getName().equals("executeQuery")&&sql.contains("FOR UPDATE")){check(!actual.getAutoCommit(),"Every observed lock query must hold its actual JDBC transaction");locks.add(Map.of("connection",id,"thread",Thread.currentThread().getName(),"sql",sql,"parameters",params.entrySet().stream().map(e->Map.of("index",e.getKey(),"value",Objects.toString(e.getValue(),"NULL"))).toList()));}
    Object value=invoke(st,sm,sa);if(target&&sm.getName().equals("executeQuery")&&sql.contains("FROM meeting_minutes_editor_guard")&&sql.contains("FOR UPDATE")&&StackWalker.getInstance().walk(frames->frames.anyMatch(f->f.getClassName().equals("ama.transcript.JdbcMinutesGenerationPreparation")&&f.getMethodName().equals("prepareExisting"))))captured.set(true);return value;
   });}return result;
  });}
  public Connection getConnection()throws SQLException{return wrap(delegate.getConnection());}public Connection getConnection(String u,String p)throws SQLException{return wrap(delegate.getConnection(u,p));}
 }
 static Map<String,Object> task(JdbcTemplate j,String id){return j.queryForMap("SELECT id,state,attempt,lease_owner,expires_at,output_id FROM durable_task WHERE id=?",id);}
 static String state(JdbcTemplate j,String id){return j.queryForObject("SELECT state FROM durable_task WHERE id=?",String.class,id);}
 static <T>T field(Object o,String name,Class<T> type)throws Exception{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return type.cast(f.get(o));}
 public static void main(String[] args)throws Exception{
  check("1".equals(System.getenv("AMA_LOCAL_DEV"))&&args.length==3,"Explicit owned coexistence qualification required");Path file=Path.of(args[0]).toRealPath(),out=Path.of(args[2]).toRealPath();check(file.getParent().endsWith(Path.of(".tools/local-app"))&&out.startsWith(file.getParent().resolve("native-coexistence")),"Exact current daily evidence scope required");var p=new Properties();try(var in=Files.newInputStream(file)){p.load(in);}String url=p.getProperty("database.url");check(url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"),"Exact owned daily DB required");var fixtures=JSON.readTree(Files.readString(Path.of(args[1])));var first=fixtures.get("first");var second=fixtures.get("second");var txt=fixtures.get("txt");var pub=fixtures.get("publication");String a=first.get("taskId").asText(),b=second.get("taskId").asText(),t=txt.get("taskId").asText(),k=pub.get("taskId").asText();for(String v:List.of(a,b,t,k))UUID.fromString(v);
  var original=ama.minutes.ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password"));var source=new Source(original);var j=new JdbcTemplate(source);j.setQueryTimeout(5);check(new HashSet<>(j.queryForList("SELECT id FROM durable_task WHERE state IN ('READY','RUNNING','RECONCILING')",String.class)).equals(Set.of(a,b,t,k)),"Only four genuine fixture tasks may be pending");check(state(j,k).equals("RECONCILING")&&j.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=? AND state='MARKED'",Long.class,k)==1,"Original actual marked publication required");
  var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var configured=ConfiguredProcessing.read(env);var definitions=ConfiguredBackends.read(env);var provider=new TranscriptWorkerRuntimeProvider(source,definitions,configured.read(),configured.canonical(),configured.preparation(),"LOCAL_COEXIST_"+out.getFileName(),1,ConfiguredMinutes.read(env,configured.read(),configured.index()),ConfiguredPublication.read(env,configured.read(),configured.index()));
  var report=new LinkedHashMap<String,Object>();
  try(var runtime=(TranscriptWorkerRuntimeProvider.Runtime)provider.create()){
   source.armed=true;runtime.start();
   try{
    check(source.arrived.await(20,TimeUnit.SECONDS),"Actual first minutes S commit must pause");var tasks=List.of(a,b).stream().map(id->task(j,id)).toList();Files.writeString(out.resolve("saturation-entry.json"),JSON.writeValueAsString(tasks.stream().map(x->Map.of("id",x.get("id"),"state",x.get("state"),"attempt",x.get("attempt"))).toList()));var running=tasks.stream().filter(x->x.get("state").equals("RUNNING")).toList();var ready=tasks.stream().filter(x->x.get("state").equals("READY")).toList();check(running.size()==1&&ready.size()==1&&((Number)running.getFirst().get("attempt")).intValue()==1&&((Number)ready.getFirst().get("attempt")).intValue()==0,"Capacity-one pool must leave second generation unclaimed");String active=(String)running.getFirst().get("id"),waiting=(String)ready.getFirst().get("id");String meeting=active.equals(a)?first.get("meetingId").asText():second.get("meetingId").asText();LocalMinutesPreparationBoundaryCheck.physicalRootFree(original,meeting);long begin=System.nanoTime(),end=begin+TimeUnit.SECONDS.toNanos(21);boolean progressed=false;
    do{check(state(j,waiting).equals("READY")&&((Number)task(j,waiting).get("attempt")).intValue()==0,"Saturation must not speculatively claim a second generation");if(state(j,t).equals("SUCCEEDED")&&state(j,k).equals("SUCCEEDED")&&System.nanoTime()-begin>=TimeUnit.SECONDS.toNanos(12)){progressed=true;break;}Thread.sleep(100);}while(System.nanoTime()<end);
    var after=task(j,active);check(after.get("state").equals("RUNNING")&&after.get("lease_owner").equals(running.getFirst().get("lease_owner"))&&((java.time.LocalDateTime)after.get("expires_at")).isAfter((java.time.LocalDateTime)running.getFirst().get("expires_at")),"Actual heartbeats must retain occupied generation lease");check(progressed,"TXT and original publication reconciliation must complete while minutes is saturated");var traffic=field(runtime,"knowledgeClient",ControlledKnowledgeClient.class).traffic();check(traffic.get("getWriteAttempts")>0&&traffic.get("postWriteAttempts")==0,"Marked publication recovery must perform actual GET and zero POST");
    report.put("whileMinutesSlotOccupied",Map.of("runningTask",active,"waitingTask",waiting,"waitingAttempt",0,"physicalRootFree",true,"heartbeatAdvanced",true,"txtSucceeded",true,"originalPublicationSucceeded",true,"pauseMillis",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-begin),"knowledgeTraffic",traffic));source.armed=false;source.resume.countDown();
    long finish=System.nanoTime()+TimeUnit.SECONDS.toNanos(90);while(System.nanoTime()<finish&&!List.of(a,b,t,k).stream().allMatch(id->state(j,id).equals("SUCCEEDED")))Thread.sleep(200);check(List.of(a,b,t,k).stream().allMatch(id->state(j,id).equals("SUCCEEDED")),"All four original tasks must succeed");
    var completed=new ArrayList<Map<String,Object>>();for(String id:List.of(a,b)){var value=task(j,id);check(j.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=?",Long.class,id)==1&&j.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Long.class,id)==1,"Each original generation has exactly one execution/candidate");check(((Number)value.get("attempt")).intValue()==1,"Each original generation must finish its first attempt");completed.add(Map.of("task",id,"attempt",value.get("attempt"),"executions",1,"candidates",1));}
    check(j.queryForObject("SELECT COUNT(*) FROM transcript_revision WHERE meeting_id=? AND kind='RAW'",Long.class,txt.get("meetingId").asText())==1&&j.queryForObject("SELECT COUNT(*) FROM task_outbox WHERE task_id=? AND event_type='TASK_SUCCEEDED'",Long.class,t)==1,"TXT single RAW/success event required");check(j.queryForObject("SELECT COUNT(*) FROM external_document_mapping WHERE publication_id=?",Long.class,pub.get("publicationId").asText())==1&&j.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=?",Long.class,k)==1,"Original publication single execution/mapping required");report.put("completedGenerations",completed);report.put("pass",true);report.put("genuineRuntimeProvider",true);report.put("minutesCapacity",1);report.put("manualSqlBusinessOrLeaseMutation",false);report.put("publicationTask",k);report.put("txtTask",t);Files.writeString(out.resolve("report.json"),JSON.writeValueAsString(report));System.out.println(JSON.writeValueAsString(report));
   }finally{source.armed=false;source.resume.countDown();}
  }finally{Files.writeString(out.resolve("locking-queries.json"),JSON.writeValueAsString(source.locks));}
 }
}
